import React, { useState } from 'react';
import axios from 'axios';
import ConnectionForm from '../components/ConnectionForm';
import ChartCard from '../components/ChartCard';
import Loader from '../components/Loader';

const API = 'http://localhost:5000/api';

export default function Dashboard() {
  const [insights, setInsights] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [step, setStep] = useState(0);
  const [dbInfo, setDbInfo] = useState(null);
  const [connStr, setConnStr] = useState('');

  const handleConnect = async (connectionString) => {
    setError('');
    setInsights([]);
    setLoading(true);
    setStep(0);
    setConnStr(connectionString);

    try {
      // Step 1–2: Connect and extract schema
      setStep(1);
      const { data: { schema, profile } } = await axios.post(`${API}/connect`, { connectionString });

      const tableCount = [...new Set(schema.map((r) => r.table_name))].length;
      setDbInfo({ tableCount, columnCount: schema.length });

      // Step 3–5: Generate insights
      setStep(2);
      const { data: { insights: generated } } = await axios.post(`${API}/insights`, {
        connectionString,
        schema,
        profile,
      });

      setStep(4);
      setInsights(generated);
    } catch (err) {
      const msg = err.response?.data?.error || err.message || 'Something went wrong.';
      setError(msg);
    } finally {
      setLoading(false);
      setStep(0);
    }
  };

  const handleReset = () => {
    setInsights([]);
    setDbInfo(null);
    setError('');
    setConnStr('');
  };

  if (loading) return <Loader currentStep={step} />;

  if (insights.length === 0) {
    return <ConnectionForm onSubmit={handleConnect} loading={loading} error={error} />;
  }

  return (
    <div style={styles.page}>
      {/* Header */}
      <header style={styles.header}>
        <div style={styles.headerLeft}>
          <span style={{ fontSize: '24px' }}>⚡</span>
          <div>
            <h1 style={styles.headerTitle}>AI Dashboard</h1>
            {dbInfo && (
              <p style={styles.headerMeta}>
                {dbInfo.tableCount} tables · {dbInfo.columnCount} columns · {insights.length} insights generated
              </p>
            )}
          </div>
        </div>
        <div style={styles.headerRight}>
          <button onClick={() => handleConnect(connStr)} style={styles.refreshBtn}>
            ↻ Regenerate
          </button>
          <button onClick={handleReset} style={styles.resetBtn}>
            ← New Connection
          </button>
        </div>
      </header>

      {/* Error banner */}
      {error && (
        <div style={styles.errorBanner}>
          ⚠️ {error}
        </div>
      )}

      {/* Stats row */}
      <div style={styles.statsRow}>
        {[
          { label: 'Insights', value: insights.length },
          { label: 'Tables', value: dbInfo?.tableCount ?? '—' },
          { label: 'Columns', value: dbInfo?.columnCount ?? '—' },
          { label: 'Charts OK', value: insights.filter((i) => !i.queryError && !i.noData).length },
        ].map((s) => (
          <div key={s.label} style={styles.statCard}>
            <span style={styles.statValue}>{s.value}</span>
            <span style={styles.statLabel}>{s.label}</span>
          </div>
        ))}
      </div>

      {/* Charts grid */}
      <div style={styles.grid}>
        {insights.map((insight, i) => (
          <ChartCard key={i} insight={insight} />
        ))}
      </div>

      <footer style={styles.footer}>
        Powered by LangChain · Groq (LLaMA 3 70B) · ECharts
      </footer>
    </div>
  );
}

const styles = {
  page: {
    minHeight: '100vh',
    background: 'linear-gradient(160deg, #0a0a1e 0%, #12122e 50%, #0a0a1e 100%)',
    padding: '0 0 60px',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
  },
  header: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: '24px 32px',
    borderBottom: '1px solid rgba(255,255,255,0.06)',
    background: 'rgba(255,255,255,0.02)',
    gap: '16px',
    flexWrap: 'wrap',
  },
  headerLeft: { display: 'flex', alignItems: 'center', gap: '14px' },
  headerTitle: { color: '#fff', fontSize: '20px', fontWeight: '700', margin: 0 },
  headerMeta: { color: 'rgba(255,255,255,0.35)', fontSize: '13px', margin: '2px 0 0' },
  headerRight: { display: 'flex', gap: '10px' },
  refreshBtn: {
    padding: '8px 18px',
    background: 'rgba(102,126,234,0.15)',
    border: '1px solid rgba(102,126,234,0.3)',
    color: '#667eea',
    borderRadius: '8px',
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: '600',
  },
  resetBtn: {
    padding: '8px 18px',
    background: 'rgba(255,255,255,0.06)',
    border: '1px solid rgba(255,255,255,0.1)',
    color: 'rgba(255,255,255,0.6)',
    borderRadius: '8px',
    cursor: 'pointer',
    fontSize: '13px',
  },
  errorBanner: {
    margin: '16px 32px 0',
    padding: '14px 20px',
    background: 'rgba(238,102,102,0.1)',
    border: '1px solid rgba(238,102,102,0.25)',
    borderRadius: '10px',
    color: '#EE6666',
    fontSize: '14px',
  },
  statsRow: {
    display: 'flex',
    gap: '16px',
    padding: '24px 32px 0',
    flexWrap: 'wrap',
  },
  statCard: {
    background: 'rgba(255,255,255,0.04)',
    border: '1px solid rgba(255,255,255,0.07)',
    borderRadius: '12px',
    padding: '16px 24px',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    minWidth: '100px',
  },
  statValue: { color: '#fff', fontSize: '28px', fontWeight: '700' },
  statLabel: { color: 'rgba(255,255,255,0.4)', fontSize: '12px', marginTop: '4px', textTransform: 'uppercase', letterSpacing: '0.5px' },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(480px, 1fr))',
    gap: '20px',
    padding: '24px 32px',
  },
  footer: {
    textAlign: 'center',
    color: 'rgba(255,255,255,0.2)',
    fontSize: '12px',
    paddingTop: '20px',
    letterSpacing: '0.5px',
  },
};
